const diasAtras = $('Escolher dia').first().json.dias_atras;
const inicio = $now.startOf('day').minus({ days: diasAtras });
const fim = inicio.plus({ days: 1 });
const de = inicio.toMillis();
const ate = fim.toMillis();
const contagem = { quente: 0, morno: 0, frio: 0, sem_faixa: 0 };
let total = 0;

for (const { json: lead } of $input.all()) {
  const criadoEm = Date.parse(lead.createdAt);
  if (!Number.isFinite(criadoEm) || criadoEm < de || criadoEm >= ate) continue;

  const faixa = String(lead.faixa ?? '').trim().toLowerCase();
  if (['quente', 'morno', 'frio'].includes(faixa)) {
    contagem[faixa] += 1;
  } else {
    contagem.sem_faixa += 1;
  }
  total += 1;
}

return [{ json: { dia: inicio.toISODate(), total, ...contagem } }];
